module.header:
/* AIR Sensor on RRH47000 Module Instance. */
/** Access the RRH47000 Module instance using these structures when calling API functions directly (::p_api is not used). */
extern rm_rrh47000_instance_ctrl_t ${module.middleware.air_sensor.name}_ctrl;
extern const rm_air_sensor_cfg_t ${module.middleware.air_sensor.name}_cfg;
#ifndef ${module.middleware.air_sensor.p_callback}
void ${module.middleware.air_sensor.p_callback}(rm_air_sensor_callback_args_t * p_args);
#endif

module.declarations:
rm_rrh47000_instance_ctrl_t ${module.middleware.air_sensor.name}_ctrl;
rm_rrh47000_extended_cfg_t ${module.middleware.air_sensor.name}_extended_cfg =
{
    .abc                     = ${module.middleware.rrh47000.abc},
    .correction_cycle_period = ${module.middleware.rrh47000.correction_cycle_period},
    .co2_baseline_value      = ${module.middleware.rrh47000.co2_baseline_value},
};
const rm_air_sensor_cfg_t ${module.middleware.air_sensor.name}_cfg =
{
    .p_comms_instance = &${module.middleware.air_sensor.requires.comms_i2c_device::module.driver.comms_i2c_device.name},
    .p_comms_callback = ${module.middleware.air_sensor.p_callback},
#if defined(${module.middleware.air_sensor.p_context})
    .p_context           = ${module.middleware.air_sensor.p_context},
#else
    .p_context           = &${module.middleware.air_sensor.p_context},
#endif
    .p_extend            = (void *)&${module.middleware.air_sensor.name}_extended_cfg,
};

const rm_air_sensor_instance_t ${module.middleware.air_sensor.name} =
{
    .p_ctrl = &${module.middleware.air_sensor.name}_ctrl,
    .p_cfg  = &${module.middleware.air_sensor.name}_cfg,
    .p_api  = &g_air_sensor_on_rrh47000,
};

template.content:
/* TODO: Enable if you want to open RRH47000 */
#define ${rrh47000_name_upper:raProperty(module.middleware.air_sensor.name_upper)}_NON_BLOCKING (0)

#if ${rrh47000_name_upper}_NON_BLOCKING
volatile bool g_rrh47000_i2c_completed = false;
#endif

/* TODO: Enable if you want to use a I2C callback */
#define ${rrh47000_name_upper}_I2C_CALLBACK_ENABLE (0)
#if ${rrh47000_name_upper}_I2C_CALLBACK_ENABLE
void ${rrh47000_callback:raProperty(module.middleware.air_sensor.p_callback)}(rm_air_sensor_callback_args_t * p_args)
{
#if ${rrh47000_name_upper}_NON_BLOCKING
    if (RM_AIR_SENSOR_EVENT_ERROR != p_args->event)
    {
        g_rrh47000_i2c_completed = true;
    }
#else
    FSP_PARAMETER_NOT_USED(p_args);
#endif
}
#endif

/* Delay */
#define ${rrh47000_name_upper}_DELAY_1000     (1000)

/* Quick setup for ${rrh47000_name:raProperty(module.middleware.air_sensor.name)}.
 * - ${i2c_bus_name:raProperty(module.driver.comms_i2c_bus.name)} must be setup before calling this function
 *     (See Developer Assistance -> ${rrh47000_name} -> ${i2c_device_name:raProperty(module.driver.comms_i2c_device.name)} -> ${i2c_bus_name} -> Quick Setup).
 */
void ${rrh47000_name}_quick_setup(void);

/* Quick setup for ${rrh47000_name}. */
void ${rrh47000_name}_quick_setup(void)
{
    fsp_err_t err;

    /* Open RRH47000 sensor instance, this must be done before calling any RRH47000 API */
    err = RM_RRH47000_Open(&${rrh47000_name}_ctrl, &${rrh47000_name}_cfg);
    assert(FSP_SUCCESS == err);
}

/* Quick getting values for ${rrh47000_name:raProperty(module.middleware.air_sensor.name)}.
 * - ${rrh47000_name} must be setup before calling this function.
 */
void ${rrh47000_name}_quick_getting_data(rm_air_sensor_data_t * p_data);

/* Quick getting gas data for ${rrh47000_name}. */
void ${rrh47000_name}_quick_getting_data(rm_air_sensor_data_t * p_data)
{
    fsp_err_t            err;
    rm_air_sensor_raw_data_t rrh47000_raw_data;
    bool is_valid_data = false;

    /* Clear the callback flag */
#if ${rrh47000_name_upper:raProperty(module.middleware.air_sensor.name_upper)}_NON_BLOCKING
    g_rrh47000_i2c_completed = false;
#endif

    do
    {
        /* Read measurement data from RRh47000 sensor module */
        err = RM_RRH47000_Read(&${rrh47000_name}_ctrl, &rrh47000_raw_data);
        assert(FSP_SUCCESS == err);
#if ${rrh47000_name_upper}_NON_BLOCKING
        while (!g_rrh47000_i2c_completed)
        {
            ;
        }
        g_rrh47000_i2c_completed = false;
#endif

        /* Calculate values from RRH47000 measurement data */
        err = RM_RRH47000_DataCalculate(&${rrh47000_name}_ctrl, &rrh47000_raw_data, p_data);
        if (FSP_SUCCESS == err)
        {
            is_valid_data = true;
        }
        else if (FSP_ERR_SENSOR_INVALID_DATA == err)
        {
            is_valid_data = false;
        }
        else
        {
            assert(false);
        }
    }
    while (false == is_valid_data);

    /* Sampling Interval */
#if BSP_CFG_RTOS == 1 // AzureOS
    tx_thread_sleep(${rrh47000_name_upper}_DELAY_1000 * TX_TIMER_TICKS_PER_SECOND / ${rrh47000_name_upper}_DELAY_MS);
#elif BSP_CFG_RTOS == 2 // FreeRTOS
    vTaskDelay(${rrh47000_name_upper}_DELAY_1000 * configTICK_RATE_HZ / ${rrh47000_name_upper}_DELAY_MS);
#else // Bare Metal
    R_BSP_SoftwareDelay(${rrh47000_name_upper}_DELAY_1000, BSP_DELAY_UNITS_MILLISECONDS);
#endif
}
